"""SDM specs (OWNER 10) of the segment-register instructions MOV Sreg, r/m16, POP Sreg and PUSH Sreg.  Every SDM quote is checked by sdm_cite_check.py against sysspec_seg_pages.tsv (generated by
sdm_pages.py); the comparison is z3 `unsat` of a difference.  A spec claims a key by DECODING it (a segment register operand), never by a key list.  The loadable selectors are read from the record
(platform/declared/x86sys.json, rows mov_to_sreg and selectors, through proof/x86sys.py); nothing of it is held here.  Result texts: sysspec_text.py.

MOV Sreg, SDM 2B:P1318
  'The MOV instruction cannot be used to load the CS register.'   (the Form: the fault #UD, always, and no effect)
  'Loading a segment register while in protected mode results in special checks and actions'
SDM 2B:P1319
  'IF DS, ES, FS, or GS is loaded with non-NULL selector'   the selector is loaded only when it names a descriptor the declared machine allows at CPL 3 (the record's mov_to_sreg selectors: the index
  with the RPL and TI bits cleared); 'THEN #GP(selector); FI;' otherwise.  The runtime reports every #GP of the declared machine as the access violation (fault kind AV, fnvlift/faults.json).
  SDM 2B:P1318  'A NULL segment selector (values 0000-0003) can be loaded' (index 0, any RPL) loads into ES, DS, FS, GS when the record's `null` says so; SS needs RPL = CPL, and the null selector is not loadable into SS ('IF SS is loaded THEN IF segment selector is NULL THEN #GP(0); FI;').
  A selector that the record leaves undecided (mov_to_sreg.undecided) cannot be classified for ES, DS, FS, GS: no Form, `uncertified: <the record's why>`.  SS does not depend on it (a code descriptor is not a writable data segment).
  The register takes the selector, FS also re-bases (fnvl_seg_set: the TEB base when the selector is the record's flat fs selector, else 0).  Nothing changes when the fault is raised.
POP Sreg, SDM 2B:P1688
  'POP instruction cannot pop a value into the CS register.'   the destination is loaded as by MOV above from the stack top (the low 16 bits of the word or doubleword); the stack pointer is incremented:
  'ESP := ESP + 4;'   for a doubleword, and 'ESP := ESP + 2;' for a word (OperandSize 16), and not when the load faults.
PUSH Sreg, SDM 2B:P1811
  'the segment selector is written on the stack using a 16-bit move'   with operand size 32 (the declared CPU is the reference host's: 'leaving the upper portion of the stack location unmodified'), and with the 66 prefix a word;
  ESP is decremented by the operand size before the store, the stack slot is ESP - operand size.
"""
import os as _q_os, sys as _q_sys
_q_sys.path.insert(0, _q_os.path.join(_q_os.path.dirname(_q_os.path.abspath(__file__)), "..", "..", ".."))   # ports (`fnvnx` is ports/fnvnx -> fnv-nx): qualified imports of another root's modules (fnvnx.contract.X, fnvnx.verify.X)
import os
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, os.path.dirname(HERE))
import capstone.x86_const as X  # noqa: E402
import z3  # noqa: E402
from fnvnx.lift.fnvlift import dsl  # noqa: E402
from fnvnx.lift.fnvlift.faults import BYNAME as FT  # noqa: E402
from fnvnx.lift.proof import symform, x86sys  # noqa: E402
import sysspec_gap as G  # noqa: E402
from sysspec_text import SEG as TEXT  # noqa: E402

K_AV, K_UD = FT['AV']['code'], FT['UD']['code']
V = G.V


def family(ins):
    """'mov' | 'pop' | 'push' when the decoded instruction's segment-register operand is the one the spec covers (MOV Sreg, r/m16 has the segment register as destination), else None"""
    m = ins.mnemonic.split()[-1]; o = ins.operands
    sreg = lambda x: x.type == X.X86_OP_REG and ins.reg_name(x.reg) in G.SREGS
    if m == 'mov' and len(o) == 2 and sreg(o[0]) and o[1].type in (X.X86_OP_MEM, X.X86_OP_REG): return 'mov'
    if m in ('pop', 'push') and len(o) == 1 and sreg(o[0]): return m
    return None


def loadable(reg, s, rec):
    """the z3 condition `the selector s (32-bit value < 2^16) loads into REG at the declared CPL`, from the record rows: SS needs RPL = CPL and a selector of the record's list; the others a selector of the list or the null one"""
    ms = rec['mov_to_sreg'][reg]; k = s & 0xfffc
    ok = z3.Or([k == i for i in sorted({v & 0xfffc for v in ms['selectors']})] + ([k == 0] if ms['null'] else [z3.BoolVal(False)]))
    return z3.And(ok, (s & 3) == x86sys.cpl(rec)) if reg == 'ss' else ok


def same(a, b):
    s = z3.Solver(); s.add(a != b)
    return s.check() == z3.unsat


def check(key, rec=None):
    ins = G.decode(key); fam = family(ins)
    if fam is None: return 'not-covered', TEXT['none']
    why = G.unclaimed_prefix(ins, key)
    if why: return 'uncertified', TEXT['unc'] % why
    rec = rec or x86sys.load()
    fields = symform.parse_key(key)[1]
    reg = ins.reg_name(ins.operands[0].reg); w = 16 if ins.prefix[2] == 0x66 else 32
    try: f = symform.symbuild(key).form
    except dsl.UndecidedRow as e:
        u = rec['mov_to_sreg']['undecided']
        return ('uncertified', TEXT['undec'] % u['why']) if u['selectors'] and reg != 'ss' else ('FAILED(dsl)', TEXT['spurious'])
    if fam != 'push' and reg not in ('ss', 'cs') and rec['mov_to_sreg']['undecided']['selectors']: return 'FAILED(dsl)', TEXT['noundecided']        # the spec says no Form exists
    d = []
    if fam == 'push':
        sel = V('sel_' + reg, 16)
        if f.faults or f.flags or f.xs or f.swhen: d.append('effects')
        if [r[0] for r in f.regs] != ['esp'] or not same(dsl.to_smt(f.regs[0][1]), V('esp') - w // 8): d.append('esp')
        want = dsl.mem_array(); a = V('esp') - w // 8
        want = z3.Store(z3.Store(want, a, z3.Extract(7, 0, sel)), a + 1, z3.Extract(15, 8, sel))       # a 16-bit move: the upper portion of a 32-bit slot is not written
        if not same(G.mem_after(f.stores), want): d.append('memory')
    else:
        if fam == 'mov':
            o = ins.operands[1]
            if o.type == X.X86_OP_MEM: a = G.ea(ins, fields); m = dsl.mem_array(); src = z3.Concat(z3.Select(m, a + 1), z3.Select(m, a))
            else: n = ins.reg_name(o.reg); src = z3.Extract(15, 0, V(n if len(n) == 3 else 'e' + n))      # the low 16 bits of the register
        else:
            m = dsl.mem_array(); a = V('esp'); src = z3.Concat(z3.Select(m, a + 1), z3.Select(m, a))      # the low 16 bits of the word or doubleword at the stack top
        s = z3.ZeroExt(16, src)
        if len(f.faults) != 1 or f.stores or f.flags or f.swhen: d.append('effects')
        else:
            code, cond = f.faults[0]
            want = (K_UD, z3.BoolVal(True)) if reg == 'cs' else (K_AV, z3.Not(loadable(reg, s, rec)))
            if code != want[0] or not same(dsl.to_smt(cond) == 1, want[1]): d.append('fault')
        want_xs = [] if reg == 'cs' else [('sel', G.SREGS.index(reg))]
        if [x[:2] for x in f.xs] != want_xs or (want_xs and not same(dsl.to_smt(f.xs[0][2]), src)): d.append('selector')
        regs = [r[0] for r in f.regs]
        if fam == 'pop':
            if regs != ['esp'] or not same(dsl.to_smt(f.regs[0][1]), V('esp') + w // 8): d.append('esp')
        elif regs: d.append('regs')
    if not same(dsl.to_smt(f.eip), V('eip') + ins.size): d.append('eip')
    return ('proved', TEXT['ok'] % (fam, reg)) if not d else ('FAILED(dsl)', TEXT['diff'] % ','.join(d))
